const pageSize_int = Number($('Config').first().json.PAGE_SIZE || 100);
const count_obj = $input.first().json;

/*	Administrate returns a failed query as HTTP 200 with an errors array and	*/
/*	no data block. Reading straight through one produces zero pages, which	*/
/*	looks exactly like a tenant with no course templates.	*/
if (count_obj.errors && count_obj.errors.length > 0)
{
	throw new Error('Course template count failed: ' + JSON.stringify(count_obj.errors).slice(0, 400));
}

if (!count_obj.data || !count_obj.data.courseTemplates || !count_obj.data.courseTemplates.pageInfo)
{
	throw new Error('Course template count returned no data block, so the register size is unknown and nothing downstream can be trusted.');
}

const total_int = Number(count_obj.data.courseTemplates.pageInfo.totalRecords || 0);
const query_str = 'query Register($after: String, $size: Int) { courseTemplates(first: $size, after: $after) { pageInfo { totalRecords hasNextPage } edges { node { id legacyId title lifecycleState achievementTypes(first: 5) { edges { node { id autoAward achievementType { id name validityPeriod { unit value } } } } } } } } }';
const out_ary = [];
let offset_int = 0;

while (offset_int < total_int)
{
	let after_var = null;
	if (offset_int > 0)
	{
		const raw_str = 'Cursor:' + (offset_int - 1);
		if (typeof Buffer !== 'undefined')
		{
			after_var = Buffer.from(raw_str, 'utf8').toString('base64');
		} else {
			after_var = btoa(raw_str);
		}
	}

	out_ary.push({ json: {
		offset: offset_int,
		gqlBody: JSON.stringify({ query: query_str, variables: { after: after_var, size: pageSize_int } })
	} });
	offset_int = offset_int + pageSize_int;
}

if (out_ary.length === 0)
{
	throw new Error('Register read produced no pages. totalRecords came back as ' + total_int + ', which should never happen on a live tenant.');
}

return out_ary;

const wantedRaw_str = String($('Config').first().json.RENEWABLE_ACHIEVEMENT_TYPE_IDS || '');
const wanted_ary = [];
const parts_ary = wantedRaw_str.split(',');
let p_int = 0;

while (p_int < parts_ary.length)
{
	const trimmed_str = parts_ary[p_int].trim();
	if (trimmed_str !== '') { wanted_ary.push(trimmed_str); }
	p_int = p_int + 1;
}

const out_ary = [];
const seen_ary = [];
const items_ary = $input.all();
let coursesSeen_int = 0;
let expectedTotal_int = 0;
let i_int = 0;

while (i_int < items_ary.length)
{
	const page_obj = items_ary[i_int].json;

	/*	A failed page used to fall through to an empty edge list, dropping up	*/
	/*	to a hundred course templates without a word and leaving the run green.	*/
	if (page_obj.errors && page_obj.errors.length > 0)
	{
		throw new Error('Register page ' + i_int + ' failed: ' + JSON.stringify(page_obj.errors).slice(0, 400));
	}

	const payload_obj = page_obj.data;

	if (!payload_obj || !payload_obj.courseTemplates)
	{
		throw new Error('Register page ' + i_int + ' returned no data block.');
	}

	const pageInfo_obj = payload_obj.courseTemplates.pageInfo || {};

	if (Number(pageInfo_obj.totalRecords || 0) > expectedTotal_int)
	{
		expectedTotal_int = Number(pageInfo_obj.totalRecords || 0);
	}

	const edges_ary = payload_obj.courseTemplates.edges || [];
	let e_int = 0;

	while (e_int < edges_ary.length)
	{
		const course_obj = edges_ary[e_int].node;
		coursesSeen_int = coursesSeen_int + 1;
		const attachments_ary = (course_obj.achievementTypes && course_obj.achievementTypes.edges) ? course_obj.achievementTypes.edges : [];
		let a_int = 0;

		while (a_int < attachments_ary.length)
		{
			const type_obj = attachments_ary[a_int].node.achievementType;
			const period_obj = type_obj ? type_obj.validityPeriod : null;

			if (type_obj && wanted_ary.indexOf(type_obj.id) !== -1 && period_obj)
			{
				let months_int = 0;
				if (period_obj.unit === 'years') { months_int = Number(period_obj.value) * 12; }
				if (period_obj.unit === 'months') { months_int = Number(period_obj.value); }

				if (months_int > 0 && seen_ary.indexOf(course_obj.id) === -1)
				{
					seen_ary.push(course_obj.id);
					out_ary.push({ json: {
						courseTemplateId: course_obj.id,
						courseLegacyId: course_obj.legacyId,
						courseTitle: String(course_obj.title || '').trim(),
						lifecycleState: course_obj.lifecycleState,
						achievementTypeId: type_obj.id,
						achievementTypeName: String(type_obj.name || '').trim(),
						validityMonths: months_int
					} });
				}
			}

			a_int = a_int + 1;
		}

		e_int = e_int + 1;
	}

	i_int = i_int + 1;
}

/*	Count the work, not the runs. Administrate caps a page at 100 whatever	*/
/*	you ask for, so a truncated read is indistinguishable from a good one	*/
/*	until the totals are compared.	*/
if (coursesSeen_int < expectedTotal_int)
{
	throw new Error('Register read is short: ' + coursesSeen_int + ' course templates read across ' + items_ary.length + ' pages, tenant reports ' + expectedTotal_int + '. A template deleted mid run is a benign cause, anything larger is a truncated read.');
}

if (out_ary.length === 0)
{
	throw new Error('No course template carries a renewable achievement type. Expected at least one of: ' + wanted_ary.join(', ') + '. Either every attachment was removed, or RENEWABLE_ACHIEVEMENT_TYPE_IDS holds ids from another tenant.');
}

return out_ary;

const config_obj = $('Config').first().json;
const notice_int = Number(config_obj.NOTICE_PERIOD_MONTHS || 6);
const windowDays_int = Number(config_obj.WINDOW_DAYS || 1);
const zone_str = String(config_obj.TIMEZONE || 'Europe/London');
const floor_str = String(config_obj.FLOOR_DATE || '').trim();
const catchupFrom_str = String(config_obj.CATCHUP_FROM || '').trim();
const catchupTo_str = String(config_obj.CATCHUP_TO || '').trim();
const isCatchup_bln = catchupFrom_str !== '' && catchupTo_str !== '';

const groups_obj = {};
const items_ary = $input.all();
let i_int = 0;

while (i_int < items_ary.length)
{
	const row_obj = items_ary[i_int].json;
	const key_str = 'm' + row_obj.validityMonths;

	if (!groups_obj[key_str])
	{
		groups_obj[key_str] = { validityMonths: row_obj.validityMonths, courseTemplateIds: [], achievementTypeId: row_obj.achievementTypeId };
	}

	groups_obj[key_str].courseTemplateIds.push(row_obj.courseTemplateId);
	i_int = i_int + 1;
}

const today_obj = DateTime.now().setZone(zone_str).startOf('day');
const keys_ary = Object.keys(groups_obj);
const out_ary = [];
const dropped_ary = [];
const summary_ary = [];
let k_int = 0;

while (k_int < keys_ary.length)
{
	const group_obj = groups_obj[keys_ary[k_int]];
	const dueOffset_int = group_obj.validityMonths - notice_int;
	let from_str = '';
	let to_str = '';

	if (isCatchup_bln)
	{
		from_str = catchupFrom_str;
		to_str = catchupTo_str;
	} else {
		const to_obj = today_obj.minus({ months: dueOffset_int });
		const from_obj = to_obj.minus({ days: windowDays_int - 1 });
		from_str = from_obj.toFormat('yyyy-MM-dd');
		to_str = to_obj.toFormat('yyyy-MM-dd');
	}

	const rawFrom_str = from_str;
	let clamped_bln = false;

	if (floor_str !== '' && from_str < floor_str)
	{
		from_str = floor_str;
		clamped_bln = true;
	}

	if (from_str <= to_str)
	{
		const countQuery_str = 'query CountDue($ct: [String], $from: String, $to: String) { learners(first: 1, filters: [{ field: courseTemplateId, operation: in, values: $ct }, { field: hasPassed, operation: eq, value: "true" }, { field: isCancelled, operation: eq, value: "false" }, { field: eventEndDate, operation: ge, value: $from }, { field: eventEndDate, operation: le, value: $to }]) { pageInfo { totalRecords } } }';

		out_ary.push({ json: {
			validityMonths: group_obj.validityMonths,
			achievementTypeId: group_obj.achievementTypeId,
			courseTemplateIds: group_obj.courseTemplateIds,
			courseCount: group_obj.courseTemplateIds.length,
			dueFrom: from_str,
			dueTo: to_str,
			runMode: isCatchup_bln ? 'catchup' : 'scheduled',
			gqlBody: JSON.stringify({ query: countQuery_str, variables: { ct: group_obj.courseTemplateIds, from: from_str, to: to_str } })
		} });
	} else {
		/*	FLOOR_DATE sits after this interval due date, so the whole group	*/
		/*	vanishes. A five year certificate comes due 54 months after the	*/
		/*	event and a three year one at 30, so a floor chosen with the three	*/
		/*	year cohort in mind can delete the five year cohort entirely.	*/
		dropped_ary.push({
			validityMonths: group_obj.validityMonths,
			courseCount: group_obj.courseTemplateIds.length,
			computedDueFrom: rawFrom_str,
			computedDueTo: to_str,
			floorDate: floor_str,
			reason: clamped_bln ? 'FLOOR_DATE is later than this interval due date' : 'computed window is inverted'
		});

		/*	Plain prose, no JSON. n8n truncates a long message containing	*/
		/*	brackets and quotes, and shows the operator the middle of it.	*/
		summary_ary.push('the ' + group_obj.validityMonths + ' month interval covering ' + group_obj.courseTemplateIds.length + ' courses, which comes due between ' + rawFrom_str + ' and ' + to_str);
	}

	k_int = k_int + 1;
}

if (out_ary.length === 0)
{
	throw new Error('No reminder can ever be sent while FLOOR_DATE is ' + floor_str + ', because it excludes every interval in use: ' + summary_ary.join(', and ') + ' - a certificate comes due its validity period minus ' + notice_int + ' months after the event, so FLOOR_DATE has to be earlier than that');
}

/*	Carry partial drops forward so a half disabled scheme shows up in the run	*/
/*	report rather than only in the reminders nobody received.	*/
let o_int = 0;

while (o_int < out_ary.length)
{
	out_ary[o_int].json.droppedGroups = dropped_ary;
	o_int = o_int + 1;
}

return out_ary;

const pageSize_int = Number($('Config').first().json.PAGE_SIZE || 100);
const groups_ary = $('Build Interval Windows').all();
const counts_ary = $input.all();
const query_str = 'query DueLearners($ct: [String], $from: String, $to: String, $after: String, $size: Int) { learners(first: $size, after: $after, filters: [{ field: courseTemplateId, operation: in, values: $ct }, { field: hasPassed, operation: eq, value: "true" }, { field: isCancelled, operation: eq, value: "false" }, { field: eventEndDate, operation: ge, value: $from }, { field: eventEndDate, operation: le, value: $to }]) { pageInfo { totalRecords hasNextPage } edges { node { id legacyId result contactId event { id legacyId end courseTemplate { id legacyId } } } } } }';
const out_ary = [];
let g_int = 0;

while (g_int < counts_ary.length)
{
	const group_obj = groups_ary[g_int].json;
	const count_obj = counts_ary[g_int].json;

	if (count_obj.errors && count_obj.errors.length > 0)
	{
		throw new Error('Due learner count failed for the ' + group_obj.validityMonths + ' month interval: ' + JSON.stringify(count_obj.errors).slice(0, 400));
	}

	if (!count_obj.data || !count_obj.data.learners || !count_obj.data.learners.pageInfo)
	{
		throw new Error('Due learner count returned no data block for the ' + group_obj.validityMonths + ' month interval, so the page count would be zero and the whole interval would be skipped in silence.');
	}

	const total_int = Number(count_obj.data.learners.pageInfo.totalRecords || 0);
	let offset_int = 0;

	while (offset_int < total_int)
	{
		let after_var = null;
		if (offset_int > 0)
		{
			const raw_str = 'Cursor:' + (offset_int - 1);
			if (typeof Buffer !== 'undefined')
			{
				after_var = Buffer.from(raw_str, 'utf8').toString('base64');
			} else {
				after_var = btoa(raw_str);
			}
		}

		out_ary.push({ json: {
			validityMonths: group_obj.validityMonths,
			achievementTypeId: group_obj.achievementTypeId,
			runMode: group_obj.runMode,
			dueFrom: group_obj.dueFrom,
			dueTo: group_obj.dueTo,
			dueTotal: total_int,
			gqlBody: JSON.stringify({ query: query_str, variables: { ct: group_obj.courseTemplateIds, from: group_obj.dueFrom, to: group_obj.dueTo, after: after_var, size: pageSize_int } })
		} });
		offset_int = offset_int + pageSize_int;
	}

	g_int = g_int + 1;
}

return out_ary;

const pages_ary = $('Build Learner Page Offsets').all();
const items_ary = $input.all();
const out_ary = [];
const expected_obj = {};
const seen_obj = {};
let i_int = 0;

while (i_int < items_ary.length)
{
	const context_obj = pages_ary[i_int].json;
	const page_obj = items_ary[i_int].json;

	/*	A dropped page here means those learners silently miss their reminder	*/
	/*	and, because nothing is written to the dedupe table for them, they are	*/
	/*	picked up tomorrow only if the window still covers them. With	*/
	/*	WINDOW_DAYS at 1 it will not.	*/
	if (page_obj.errors && page_obj.errors.length > 0)
	{
		throw new Error('Due learner page ' + i_int + ' failed: ' + JSON.stringify(page_obj.errors).slice(0, 400));
	}

	const payload_obj = page_obj.data;

	if (!payload_obj || !payload_obj.learners)
	{
		throw new Error('Due learner page ' + i_int + ' returned no data block.');
	}

	const key_str = 'm' + context_obj.validityMonths;
	expected_obj[key_str] = Number(context_obj.dueTotal || 0);
	if (!seen_obj[key_str]) { seen_obj[key_str] = 0; }

	const edges_ary = payload_obj.learners.edges || [];
	seen_obj[key_str] = seen_obj[key_str] + edges_ary.length;
	let e_int = 0;

	while (e_int < edges_ary.length)
	{
		const learner_obj = edges_ary[e_int].node;
		const event_obj = learner_obj.event || {};
		const course_obj = event_obj.courseTemplate || {};

		out_ary.push({ json: {
			learnerId: learner_obj.id,
			learnerLegacyId: learner_obj.legacyId,
			contactId: learner_obj.contactId,
			result: learner_obj.result,
			eventId: event_obj.id,
			eventLegacyId: event_obj.legacyId,
			eventEnd: event_obj.end,
			courseTemplateId: course_obj.id,
			courseTemplateLegacyId: course_obj.legacyId,
			validityMonths: context_obj.validityMonths,
			achievementTypeId: context_obj.achievementTypeId,
			runMode: context_obj.runMode
		} });
		e_int = e_int + 1;
	}

	i_int = i_int + 1;
}

const checkKeys_ary = Object.keys(expected_obj);
let c_int = 0;

while (c_int < checkKeys_ary.length)
{
	const key_str = checkKeys_ary[c_int];

	if (seen_obj[key_str] < expected_obj[key_str])
	{
		throw new Error('Due learner read is short for interval ' + key_str + ': read ' + seen_obj[key_str] + ' of ' + expected_obj[key_str] + '. A truncated read means real delegates silently miss their reminder.');
	}

	c_int = c_int + 1;
}

return out_ary;

const config_obj = $('Config').first().json;
const cap_int = Number(config_obj.MAX_PER_RUN || 50);
const abortAbove_int = Number(config_obj.ABORT_ABOVE || 0);
const due_ary = $('Flatten Due Learners').all();
const sent_ary = $('Read Sent Log').all();

/*	The sent log is now read once per due event rather than in full, so this	*/
/*	holds only the rows for events actually in play. A Set rather than an array	*/
/*	scan because a catch up run makes both sides large at once.	*/
const sentKeys_set = new Set();
let s_int = 0;

while (s_int < sent_ary.length)
{
	const row_obj = sent_ary[s_int].json;

	/*	alwaysOutputData synthesises an empty item when an event has no rows	*/
	/*	yet, which is the normal case on a first run.	*/
	if (row_obj && row_obj.learner_id)
	{
		sentKeys_set.add(String(row_obj.learner_id) + '|' + String(row_obj.event_id));
	}

	s_int = s_int + 1;
}

const candidates_ary = [];
let skippedDuplicate_int = 0;
let d_int = 0;

while (d_int < due_ary.length)
{
	const row_obj = due_ary[d_int].json;
	const key_str = String(row_obj.learnerId) + '|' + String(row_obj.eventId);

	if (sentKeys_set.has(key_str))
	{
		skippedDuplicate_int = skippedDuplicate_int + 1;
	} else {
		row_obj.dedupeKey = key_str;
		candidates_ary.push(row_obj);
	}

	d_int = d_int + 1;
}

/*	MAX_PER_RUN throttles, it does not protect. If the selection itself has gone	*/
/*	wrong, a throttle still mails whatever fits and calls it a good day's work.	*/
/*	ABORT_ABOVE refuses the whole run instead, which is the right answer when	*/
/*	the number is absurd rather than merely large.	*/
if (abortAbove_int > 0 && candidates_ary.length > abortAbove_int)
{
	throw new Error('Refusing to send: ' + candidates_ary.length + ' learners are due after deduplication, which is above ABORT_ABOVE of ' + abortAbove_int + '. A number this size usually means the selection is wrong rather than the day being busy. Nothing has been sent');
}

const out_ary = [];
let c_int = 0;

while (c_int < candidates_ary.length && out_ary.length < cap_int)
{
	out_ary.push({ json: candidates_ary[c_int] });
	c_int = c_int + 1;
}

const suppressed_int = candidates_ary.length - out_ary.length;
let o_int = 0;

while (o_int < out_ary.length)
{
	out_ary[o_int].json.dueCount = due_ary.length;
	out_ary[o_int].json.skippedDuplicate = skippedDuplicate_int;
	out_ary[o_int].json.suppressedByCap = suppressed_int;
	out_ary[o_int].json.sentRowsRead = sent_ary.length;
	o_int = o_int + 1;
}

return out_ary;

const config_obj = $('Config').first().json;
const templateId_str = String(config_obj.TEMPLATE_ID || '').trim();
const sendingAddressId_str = String(config_obj.SENDING_ADDRESS_ID || '').trim();
const audienceRaw_str = String(config_obj.SEND_AUDIENCE || '').trim();
const isDryRun_bln = String(config_obj.DRY_RUN) === 'true';

/*	sendBulkLearnerAdhocEmail accepts the call with neither a template nor a	*/
/*	sending address, so without this guard the only thing between a flipped	*/
/*	DRY_RUN and a batch of unbranded mail is whoever flipped it. Leave both	*/
/*	empty until they are known and this guard keeps the run from sending.	*/
if (!isDryRun_bln)
{
	const missing_ary = [];
	if (templateId_str === '') { missing_ary.push('TEMPLATE_ID'); }
	if (sendingAddressId_str === '') { missing_ary.push('SENDING_ADDRESS_ID'); }

	if (missing_ary.length > 0)
	{
		throw new Error('Refusing to send: ' + missing_ary.join(' and ') + ' empty in Config. Fill them for this tenant, or set DRY_RUN back to true.');
	}
}

const mutation_str = 'mutation SendReminder($input: SendBulkLearnerAdhocEmailInput!) { bulkAdhocEmails { sendBulkLearnerAdhocEmail(input: $input) { errors { label message value } } } }';
const groups_obj = {};
const items_ary = $input.all();
let i_int = 0;

while (i_int < items_ary.length)
{
	const row_obj = items_ary[i_int].json;
	const key_str = String(row_obj.eventId);

	if (!groups_obj[key_str])
	{
		groups_obj[key_str] = { eventId: row_obj.eventId, eventLegacyId: row_obj.eventLegacyId, learners: [] };
	}

	groups_obj[key_str].learners.push(row_obj);
	i_int = i_int + 1;
}

/*	learnerIds and audience intersect rather than union. Audience can only narrow,	*/
/*	so setting passed means a dropped learner list can never reach a whole event.	*/
const audience_ary = [];
const parts_ary = audienceRaw_str.split(',');
let a_int = 0;

while (a_int < parts_ary.length)
{
	const trimmed_str = parts_ary[a_int].trim();
	if (trimmed_str !== '') { audience_ary.push(trimmed_str); }
	a_int = a_int + 1;
}

const keys_ary = Object.keys(groups_obj);
const out_ary = [];
let k_int = 0;

while (k_int < keys_ary.length)
{
	const group_obj = groups_obj[keys_ary[k_int]];
	const learnerIds_ary = [];
	let l_int = 0;

	while (l_int < group_obj.learners.length)
	{
		learnerIds_ary.push(group_obj.learners[l_int].learnerId);
		l_int = l_int + 1;
	}

	const input_obj = { eventId: group_obj.eventId, learnerIds: learnerIds_ary };
	if (audience_ary.length > 0) { input_obj.audience = audience_ary; }
	if (templateId_str !== '') { input_obj.templateId = templateId_str; }
	if (sendingAddressId_str !== '') { input_obj.sendingAddressId = sendingAddressId_str; }

	out_ary.push({ json: {
		eventId: group_obj.eventId,
		eventLegacyId: group_obj.eventLegacyId,
		learnerCount: learnerIds_ary.length,
		audience: audience_ary,
		learners: group_obj.learners,
		gqlBody: JSON.stringify({ query: mutation_str, variables: { input: input_obj } })
	} });
	k_int = k_int + 1;
}

return out_ary;

const items_ary = $input.all();
const rows_ary = [];
let totalLearners_int = 0;
let i_int = 0;

while (i_int < items_ary.length)
{
	const group_obj = items_ary[i_int].json;
	let l_int = 0;

	while (l_int < group_obj.learners.length)
	{
		const learner_obj = group_obj.learners[l_int];
		rows_ary.push({
			learnerId: learner_obj.learnerId,
			contactId: learner_obj.contactId,
			eventId: learner_obj.eventId,
			eventEnd: learner_obj.eventEnd,
			validityMonths: learner_obj.validityMonths,
			runMode: learner_obj.runMode
		});
		totalLearners_int = totalLearners_int + 1;
		l_int = l_int + 1;
	}

	i_int = i_int + 1;
}

const first_obj = (items_ary.length > 0 && items_ary[0].json.learners.length > 0) ? items_ary[0].json.learners[0] : {};
let dropped_ary = [];

try
{
	dropped_ary = $('Build Interval Windows').first().json.droppedGroups || [];
} catch (error) {}

return [{ json: {
	mode: 'DRY RUN, nothing sent',
	tenant: 'YOUR-INSTANCE',
	events: items_ary.length,
	learners: totalLearners_int,
	dueCount: first_obj.dueCount || 0,
	skippedDuplicate: first_obj.skippedDuplicate || 0,
	suppressedByCap: first_obj.suppressedByCap || 0,
	sentRowsRead: first_obj.sentRowsRead || 0,
	droppedGroups: dropped_ary,
	rows: rows_ary
} }];

/*	One event per iteration, so the current group is the loop's single item.	*/
/*	This used to index positionally into Group By Event, which was wrong the	*/
/*	moment any event failed: the false branch of Send Errors? carries fewer	*/
/*	items than Group By Event produced, so every event after a failure was	*/
/*	recorded against the wrong one.	*/
const group_obj = $('Send Loop').first().json;
const learners_ary = group_obj.learners || [];

if (!group_obj.eventId || learners_ary.length === 0)
{
	throw new Error('Expand Sent Learners could not read the current loop item. Refusing to write dedupe rows that may belong to another event.');
}

const sentAt_str = DateTime.now().toISO();
const out_ary = [];
let l_int = 0;

while (l_int < learners_ary.length)
{
	const learner_obj = learners_ary[l_int];
	out_ary.push({ json: {
		learner_id: String(learner_obj.learnerId),
		event_id: String(learner_obj.eventId),
		contact_id: String(learner_obj.contactId || ''),
		course_template_id: String(learner_obj.courseTemplateId || ''),
		achievement_type_id: String(learner_obj.achievementTypeId || ''),
		event_end: String(learner_obj.eventEnd || ''),
		validity_months: Number(learner_obj.validityMonths || 0),
		sent_at: sentAt_str,
		run_mode: String(learner_obj.runMode || 'scheduled')
	} });
	l_int = l_int + 1;
}

return out_ary;

/*	One status item per iteration, fed back into Send Loop. The loop collects	*/
/*	these and releases them all on its done output for Run Summary to read.	*/
const group_obj = $('Send Loop').first().json;

return [{ json: {
	eventId: group_obj.eventId,
	eventLegacyId: group_obj.eventLegacyId,
	learnerCount: group_obj.learnerCount,
	status: 'sent'
} }];

/*	Record why this event failed, then hand control back to Send Loop so the	*/
/*	remaining events still get their turn. Run Summary re-raises at the end.	*/
const group_obj = $('Send Loop').first().json;
let message_str = 'Unknown error';

try
{
	const response_obj = $('Send Reminder').first().json;
	const top_ary = response_obj.errors || [];
	const data_obj = response_obj.data || {};
	const bulk_obj = data_obj.bulkAdhocEmails || {};
	const send_obj = bulk_obj.sendBulkLearnerAdhocEmail || {};
	const nested_ary = send_obj.errors || [];

	if (top_ary.length > 0)
	{
		message_str = JSON.stringify(top_ary).slice(0, 500);
	} else if (nested_ary.length > 0) {
		message_str = JSON.stringify(nested_ary).slice(0, 500);
	} else {
		message_str = 'Send returned no usable data block';
	}
} catch (error) {
	message_str = 'Could not read the send response: ' + String(error.message || error);
}

return [{ json: {
	eventId: group_obj.eventId,
	eventLegacyId: group_obj.eventLegacyId,
	learnerCount: group_obj.learnerCount,
	status: 'failed',
	error: message_str
} }];

/*	Fired once on the loop's done output, holding one status item per event.	*/
/*	Failures are collected rather than raised inline so that a failure on one	*/
/*	event does not stop the events behind it from sending.	*/
const items_ary = $input.all();
const failed_ary = [];
let sentEvents_int = 0;
let sentLearners_int = 0;
let i_int = 0;

while (i_int < items_ary.length)
{
	const row_obj = items_ary[i_int].json;

	if (row_obj.status === 'failed')
	{
		failed_ary.push({ eventId: row_obj.eventId, error: row_obj.error });
	} else {
		sentEvents_int = sentEvents_int + 1;
		sentLearners_int = sentLearners_int + Number(row_obj.learnerCount || 0);
	}

	i_int = i_int + 1;
}

let dropped_ary = [];
let suppressed_int = 0;

try
{
	dropped_ary = $('Build Interval Windows').first().json.droppedGroups || [];
} catch (error) {}

try
{
	suppressed_int = Number($('Select Sendable').first().json.suppressedByCap || 0);
} catch (error) {}

/*	A run that quietly did nine tenths of its work is the defect class this whole	*/
/*	build exists to remove, so anything left undone turns the execution red.	*/
/*	Dropped intervals are reported but deliberately do NOT turn it red: that is a	*/
/*	standing configuration state rather than an event, and it would fire every	*/
/*	day until FLOOR_DATE changed, which is how alerts get ignored.	*/
/*	Counts are phrased as labels rather than sentences so the message reads	*/
/*	correctly at one as well as at many.	*/
const problems_ary = [];

if (failed_ary.length > 0)
{
	problems_ary.push('events that failed to send ' + failed_ary.length + ' of ' + items_ary.length);
}

if (suppressed_int > 0)
{
	problems_ary.push('learners held back by MAX_PER_RUN ' + suppressed_int + ', who stay unreminded until a later run has room');
}

let runError_str = '';

if (problems_ary.length > 0)
{
	runError_str = 'Certificate renewal reminder finished with work outstanding: ' + problems_ary.join(', and ') + '. Already sent and recorded in the dedupe table this run, so a re-run will not duplicate them: events ' + sentEvents_int + ', learners ' + sentLearners_int;
}

return [{ json: {
	eventsProcessed: items_ary.length,
	eventsSent: sentEvents_int,
	learnersSent: sentLearners_int,
	eventsFailed: failed_ary.length,
	suppressedByCap: suppressed_int,
	failures: failed_ary,
	droppedGroups: dropped_ary,
	runError: runError_str
} }];

/*	The dedupe read used to pull every row in the table and filter in memory.	*/
/*	Fine at a few hundred a month, not fine once a catch up run has put tens of thousands	*/
/*	of rows in it. Reading once per due event keeps the daily cost flat as the	*/
/*	table grows, because the number of events due on a given day does not.	*/
const items_ary = $input.all();
const seen_ary = [];
const out_ary = [];
let i_int = 0;

while (i_int < items_ary.length)
{
	const eventId_str = String(items_ary[i_int].json.eventId || '');

	if (eventId_str !== '' && seen_ary.indexOf(eventId_str) === -1)
	{
		seen_ary.push(eventId_str);
		out_ary.push({ json: { eventId: eventId_str } });
	}

	i_int = i_int + 1;
}

/*	Falling quiet here would mean the dedupe read has nothing to filter on, so	*/
/*	every learner would look unsent and every one of them would be mailed again.	*/
if (items_ary.length > 0 && out_ary.length === 0)
{
	throw new Error('Due learners were found but none carried an event id, so the dedupe read would match nothing and every learner would be treated as never reminded');
}

return out_ary;
